-- 014: the ALTER and DROP DDL required by the project brief (Req. 5), each with a real reason.
--
-- ALTER TABLE ... ADD COLUMN / ADD CONSTRAINT : record the PROVENANCE of every waste figure.
--   Part 2 introduced three ways a waste_event can come into existence - typed in by staff, imported from a
--   MongoDB field log by the ETL, or generated by the system (redistribution record, procedure-created rows).
--   Dashboards and audits need to tell them apart ("how much of this number was measured by a person?").
--   The column is derived by the existing BEFORE INSERT trigger, so the application cannot mislabel a row.
--
-- DROP INDEX : idx_wastenote_vec was created in Part 1 for "similar past incidents" search over
--   waste_event.notes_embedding. That feature was never built and the column is NULL in every row
--   (verified: SELECT count(notes_embedding) FROM waste_event = 0; idx_scan = 0 on every partition's copy).
--   An HNSW index on a 55k-row partitioned table that is never queried only costs write time and disk.
--   It can be recreated in one statement if the feature is ever built:
--     CREATE INDEX idx_wastenote_vec ON waste_event USING hnsw (notes_embedding vector_cosine_ops);

-- 1. ALTER: add the column with a constant default (no table rewrite in PostgreSQL 11+), then the rule.
ALTER TABLE waste_event ADD COLUMN measurement_source VARCHAR(12) NOT NULL DEFAULT 'MANUAL';
ALTER TABLE waste_event ADD CONSTRAINT ck_waste_measurement_source
  CHECK (measurement_source IN ('MANUAL', 'ETL_IMPORT', 'SYSTEM'));

-- 2. Back-fill provenance for rows that already exist (a no-op on an empty database).
UPDATE waste_event SET measurement_source = 'ETL_IMPORT' WHERE source_doc_id IS NOT NULL;
UPDATE waste_event w SET measurement_source = 'SYSTEM'
  FROM waste_reason r WHERE r.reason_id = w.reason_id AND r.reason_code = 'REDISTRIBUTED' AND w.source_doc_id IS NULL;

-- 3. Keep the derivation in the database: extend trigger T2 (cost + CO2e) with provenance.
--    Rows with a Mongo lineage are ETL imports; redistribution records are system-generated; anything else keeps
--    whatever the writer set ('MANUAL' by default; the close-session procedure sets 'SYSTEM' explicitly).
CREATE OR REPLACE FUNCTION trg_enrich_waste() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.food_id IS NOT NULL THEN
    SELECT NEW.quantity_kg * fi.avg_cost_per_unit,
           NEW.quantity_kg * COALESCE(ef.kg_co2e_per_kg, 2.5)
      INTO NEW.cost_estimate, NEW.co2e_estimate
      FROM food_item fi
      LEFT JOIN emission_factor ef ON ef.food_category_id = fi.food_category_id
     WHERE fi.food_id = NEW.food_id;
  END IF;
  IF NEW.source_doc_id IS NOT NULL THEN
    NEW.measurement_source := 'ETL_IMPORT';
  ELSIF EXISTS (SELECT 1 FROM waste_reason r WHERE r.reason_id = NEW.reason_id AND r.reason_code = 'REDISTRIBUTED') THEN
    NEW.measurement_source := 'SYSTEM';
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;

-- 4. DROP: the unused vector index (see header).
DROP INDEX IF EXISTS idx_wastenote_vec;

COMMENT ON COLUMN waste_event.measurement_source IS 'Provenance: MANUAL (typed in), ETL_IMPORT (from a MongoDB field log), SYSTEM (generated by a procedure/trigger).';
